      }

      .option-panel-header {
        padding: 14px 18px;
        font-size: 0.98em;
        font-weight: 700;
        background: #FEEFF4; /* 草莓牛奶色 */
        border-bottom: 1.5px solid #FBCFE8;
        text-align: center;
        letter-spacing: 0.5px;
        color: #584964;
        position: relative;
      }

      /* 可爱的装饰线 */
      .option-panel-header::after {
        content: '';
        display: block;
        width: 50px;
        height: 2px;
        margin: 8px auto 0;
        background: linear-gradient(90deg, #F472B6, #F9A8D4, #FBCFE8);
        border-radius: 2px;
        opacity: 0.7;
      }

      /* 标题两侧的小星星装饰 */
      .option-panel-header::before {
        content: '✨';
        position: absolute;
        left: 12px;
        top: 50%;
        transform: translateY(-50%);
        font-size: 1.2em;
        animation: twinkle 2s ease-in-out infinite;
      }

      @keyframes twinkle {
        0%, 100% { opacity: 1; transform: translateY(-50%) scale(1); }
        50% { opacity: 0.6; transform: translateY(-50%) scale(0.9); }
      }

      .option-list {
        list-style: none;
        padding: 14px 16px;
        margin: 0;
