      .option-item {
        background: rgba(254, 239, 244, 0.5); /* 浅粉色背景 */
        border-radius: 12px;
        transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
        border: 1.5px solid rgba(251, 207, 232, 0.4);
        position: relative;
        overflow: hidden;
      }

      /* 左侧彩色条 */
      .option-item::before {
        content: '';
        position: absolute;
        top: 0;
        left: 0;
        width: 3px;
        height: 100%;
        background: var(--accent);
        opacity: 0;
        transition: opacity 0.3s ease;
        border-radius: 12px 0 0 12px;
      }

